/// <summary>
/// PaffH 17.08.22
/// </summary>
/// <param name = "_NDXProdIdentLine22LabelArea">RefRecId to NDXProdIdentLine22LabelArea</param>
/// <param name = "_NDXProdIdentBlockTable">RefRecId to NDXProdIdentBlockTable</param>
/// <param name = "_allRest">NDXProdIdentBlockAllRest</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXProdIdentBlock2LabelArea</returns>
public static NDXProdIdentBlock2LabelArea find(
    RefRecId _NDXProdIdentLine22LabelArea,
    RefRecId _NDXProdIdentBlockTable,
    NDXProdIdentBlockAllRest _allRest,
    boolean _forUpdate = true)
{
    NDXProdIdentBlock2LabelArea nDXProdIdentBlock2LabelArea;
    nDXProdIdentBlock2LabelArea.selectForUpdate(_forUpdate);
    select firstonly nDXProdIdentBlock2LabelArea
        where nDXProdIdentBlock2LabelArea.NDXProdIdentLine22LabelArea == _NDXProdIdentLine22LabelArea
        && nDXProdIdentBlock2LabelArea.NDXProdIdentBlockTable == _NDXProdIdentBlockTable
        && nDXProdIdentBlock2LabelArea.AllRest == _allRest;

    return nDXProdIdentBlock2LabelArea;
}

/// <summary>
/// PaffH 17.08.22
/// </summary>
/// <param name = "_NDXProdIdentLine22LabelArea">RefRecId to NDXProdIdentLine22LabelArea</param>
/// <param name = "_NDXProdIdentBlockTable">RefRecId to NDXProdIdentBlockTable</param>
/// <param name = "_allRest">NDXProdIdentBlockAllRest</param>
/// <param name = "_doInsert">boolean: insert new record?</param>
/// <returns>NDXProdIdentBlock2LabelArea</returns>
public static NDXProdIdentBlock2LabelArea findOrCreate(
    RefRecId _NDXProdIdentLine22LabelArea,
    RefRecId _NDXProdIdentBlockTable,
    NDXProdIdentBlockAllRest _allRest,
    boolean _doInsert = true)
{
    NDXProdIdentBlock2LabelArea nDXProdIdentBlock2LabelArea;
    nDXProdIdentBlock2LabelArea = NDXProdIdentBlock2LabelArea::find(_NDXProdIdentLine22LabelArea, _NDXProdIdentBlockTable, _allRest, true);
    if (!nDXProdIdentBlock2LabelArea)
    {
        nDXProdIdentBlock2LabelArea.NDXProdIdentLine22LabelArea = _NDXProdIdentLine22LabelArea;
        nDXProdIdentBlock2LabelArea.NDXProdIdentBlockTable = _NDXProdIdentBlockTable;
        nDXProdIdentBlock2LabelArea.AllRest = _allRest;
        if (_doInsert)
        {
            nDXProdIdentBlock2LabelArea.insert();
        }
    }
    return nDXProdIdentBlock2LabelArea;
}

/// <summary>
/// PaffH 17.03.23
/// AX2009: table.NDX_ProdIdent_Block2LabelArea.tblBlockSelection()
/// </summary>
/// <returns>NDXProdIdentBlock2ItemId</returns>
private NDXProdIdentBlock2ItemId tblBlockSelection()
{
    NDXProdIdentBlock2ItemId      nDXProdIdentBlock2ItemIdTmp;
    NDXProdIdentBlock2ItemId      nDXProdIdentBlock2ItemId;
    NDXProdIdentProcedureLine2    nDXProdIdentProcedureLine2t;
    NDXProdIdentProcedureLine2    nDXProdIdentProcedureLine2;
    NDXProdIdentLine22LabelArea   nDXProdIdentLine22LabelArea;
    NDXProdIdentBlock2LabelArea   nDXProdIdentBlock2LabelArea;

    Query                   q = new Query();
    QueryRun                qr;
    container               conBlockId;
    boolean                 lFreeTextField;

    //BP Deviation Documented
    nDXProdIdentBlock2ItemIdTmp.setTmp();
    if (this.NDXProdIdentBlockTable)
    {
        QueryBuildDataSource qbdsNDXProdIdentBlock2ItemId = q.addDataSource(tablenum(NDXProdIdentBlock2ItemId));
        QueryBuildDataSource qbdsNDXProdIdentProcedureLine2 = qbdsNDXProdIdentBlock2ItemId.addDataSource(tablenum(NDXProdIdentProcedureLine2));
        qbdsNDXProdIdentProcedureLine2.joinMode(JoinMode::InnerJoin);
        qbdsNDXProdIdentProcedureLine2.relations(true);
        QueryBuildDataSource qbdsNDXProdIdentLine22LabelArea = qbdsNDXProdIdentProcedureLine2.addDataSource(tablenum(NDXProdIdentLine22LabelArea));
        qbdsNDXProdIdentLine22LabelArea.joinMode(JoinMode::InnerJoin);
        qbdsNDXProdIdentLine22LabelArea.relations(true);
        QueryBuildDataSource qbdsNDXProdIdentBlock2LabelArea = qbdsNDXProdIdentLine22LabelArea.addDataSource(tablenum(NDXProdIdentBlock2LabelArea));
        qbdsNDXProdIdentBlock2LabelArea.joinMode(JoinMode::InnerJoin);
        qbdsNDXProdIdentBlock2LabelArea.relations(true);

        qbdsNDXProdIdentBlock2LabelArea.addRange(fieldnum(NDXProdIdentBlock2LabelArea, NDXProdIdentLine22LabelArea)).value(QueryValue(this.NDXProdIdentLine22LabelArea));
        qbdsNDXProdIdentBlock2ItemId.addRange(fieldnum(NDXProdIdentBlock2ItemId, NDXProdIdentBlockTable)).value(queryValue(this.NDXProdIdentBlockTable));
        qbdsNDXProdIdentBlock2LabelArea.addRange(fieldnum(NDXProdIdentBlock2LabelArea, NDXProdIdentBlockTable)).value(queryValue(this.NDXProdIdentBlockTable));

        qr = new QueryRun(q);
        while (qr.next())
        {
            nDXProdIdentBlock2ItemId = qr.get(tablenum(NDXProdIdentBlock2ItemId));
            lFreeTextField = (nDXProdIdentBlock2ItemId.IsFreeText == NoYes::Yes && nDXProdIdentBlock2ItemId.FreeTextField);
            if (lFreeTextField || nDXProdIdentBlock2ItemId.BlockIdFieldName)
            {
                buf2Buf(nDXProdIdentBlock2ItemId, nDXProdIdentBlock2ItemIdTmp);
                nDXProdIdentBlock2ItemIdTmp.insert();
            }
        }
    }
    else
    {
        // Kennzeichnungsverfahren ermitteln
        select firstonly nDXProdIdentProcedureLine2t
        join nDXProdIdentLine22LabelArea
            where nDXProdIdentLine22LabelArea.NDXProdIdentProcedureLine2 == nDXProdIdentProcedureLine2t.RecId
        join nDXProdIdentBlock2LabelArea
            where nDXProdIdentBlock2LabelArea.NDXProdIdentLine22LabelArea == nDXProdIdentLine22LabelArea.RecId
                && nDXProdIdentBlock2LabelArea.RecId == this.RecId;

        // alle BlockId's ermitten
        while select * from nDXProdIdentBlock2LabelArea
        where nDXProdIdentBlock2LabelArea.NDXProdIdentBlockTable
        join nDXProdIdentLine22LabelArea
            where nDXProdIdentBlock2LabelArea.NDXProdIdentLine22LabelArea == nDXProdIdentLine22LabelArea.RecId
        join nDXProdIdentProcedureLine2
            where nDXProdIdentLine22LabelArea.NDXProdIdentProcedureLine2 == nDXProdIdentProcedureLine2.RecId
                && nDXProdIdentProcedureLine2.NDXProdIdentProcedureLine1 == nDXProdIdentProcedureLine2t.NDXProdIdentProcedureLine1
                && nDXProdIdentProcedureLine2.IDSort == nDXProdIdentProcedureLine2t.IDSort
        {
            conBlockId += nDXProdIdentBlock2LabelArea.NDXProdIdentBlockTable;
        }
        // ermittelte BlockId's ausschließen
        QueryBuildDataSource qbdsNDXProdIdentBlock2ItemId = q.addDataSource(tablenum(NDXProdIdentBlock2ItemId));
        qbdsNDXProdIdentBlock2ItemId.addRange(fieldnum(NDXProdIdentBlock2ItemId, NDXProdIdentProcedureLine1)).value(QueryValue(nDXProdIdentProcedureLine2t.NDXProdIdentProcedureLine1));
        qbdsNDXProdIdentBlock2ItemId.addRange(fieldnum(NDXProdIdentBlock2ItemId, IDSort)).value(QueryValue(nDXProdIdentProcedureLine2t.IDSort));
        QueryBuildDataSource qbdsNDXProdIdentProcedureLine2 = qbdsNDXProdIdentBlock2ItemId.addDataSource(tablenum(NDXProdIdentProcedureLine2));
        qbdsNDXProdIdentProcedureLine2.joinMode(JoinMode::InnerJoin);
        qbdsNDXProdIdentProcedureLine2.relations(true);
        qr = new QueryRun(q);
        while (qr.next())
        {
            nDXProdIdentBlock2ItemId = qr.get(tablenum(NDXProdIdentBlock2ItemId));
            if (!confind(conBlockId, nDXProdIdentBlock2ItemId.NDXProdIdentBlockTable))
            {
                buf2Buf(nDXProdIdentBlock2ItemId, nDXProdIdentBlock2ItemIdTmp);
                nDXProdIdentBlock2ItemIdTmp.insert();
            }
        }
    }
    return nDXProdIdentBlock2ItemIdTmp;

}

/// <summary>
/// PaffH 17.03.23
/// AX2009: tables.NDX_ProdIdent_Block2LabelArea.conBlockSelection()
/// </summary>
/// <returns>container</returns>
private container conBlockSelection()
{
    container   conRet;

    NDXProdIdentBlock2ItemId nDXProdIdentBlock2ItemIdTmp = this.tblBlockSelection();
    while select nDXProdIdentBlock2ItemIdTmp
    {
        boolean lFreeTextField = (nDXProdIdentBlock2ItemIdTmp.IsFreeText == NoYes::Yes && nDXProdIdentBlock2ItemIdTmp.FreeTextField);

        if (lFreeTextField || nDXProdIdentBlock2ItemIdTmp.BlockIdFieldName)
        {
            conRet += lFreeTextField ? nDXProdIdentBlock2ItemIdTmp.FreeTextField : nDXProdIdentBlock2ItemIdTmp.BlockIdFieldName;
        }
    }
    return conRet;
}

/// <summary>
/// PaffH 17.03.23
/// AX2009: tables.NDX_ProdIdent_Block2LabelArea.getBlockSelection()
/// </summary>
/// <returns>container (conBlockSelection) as string</returns>
[SysClientCacheDataMethod(true)]
display NDXProdidentBlockSelection getBlockSelection()
{
    return con2Str(this.conBlockSelection(), '; ');
}

/// <summary>
/// PaffH 07.01.25
/// AX2009: tables.NDX_ProdIdent_Block2LabelArea.getFirst_NDX_ProdIdent_Block2ItemId()
/// </summary>
/// <param name = "_NDXProdIdentBlockTableRecId">RefRecId</param>
/// <returns>NDXProdIdentBlock2ItemId</returns>
NDXProdIdentBlock2ItemId getFirstNDXProdIdentBlock2ItemId(RefRecId _NDXProdIdentBlockTableRecId)
{
    NDXProdIdentBlock2ItemId nDXProdIdentBlock2ItemId;
    NDXProdIdentProcedureLine2 nDXProdIdentProcedureLine2;
    NDXProdIdentLine22LabelArea nDXProdIdentLine22LabelArea;
    select firstonly nDXProdIdentBlock2ItemId
        where nDXProdIdentBlock2ItemId.NDXProdIdentBlockTable == _NDXProdIdentBlockTableRecId
        join nDXProdIdentProcedureLine2
        where nDXProdIdentProcedureLine2.NDXProdIdentProcedureLine1 == nDXProdIdentBlock2ItemId.NDXProdIdentProcedureLine1
        && nDXProdIdentProcedureLine2.IDSort == nDXProdIdentBlock2ItemId.IDSort
        join nDXProdIdentLine22LabelArea
        where nDXProdIdentLine22LabelArea.NDXProdIdentProcedureLine2 == nDXProdIdentProcedureLine2.RecId
        && nDXProdIdentLine22LabelArea.RecId == this.NDXProdIdentLine22LabelArea;
    return nDXProdIdentBlock2ItemId;
}

/// <summary>
/// PaffH 07.01.25
/// AX2009: tables.NDX_ProdIdent_Block2LabelArea.modifiedField()
/// </summary>
/// <param name = "_fieldId"></param>
public void modifiedField(FieldId _fieldId)
{
    const int subIdRest = 99;
    super(_fieldId);
    switch (_fieldId)
    {
        case fieldNum(NDXProdIdentBlock2LabelArea, AllRest):
            this.SubId = subIdRest;
            break;
        case fieldNum(NDXProdIdentBlock2LabelArea, NDXProdIdentBlockTable):
            NDXProdIdentBlock2ItemId nDXProdIdentBlock2ItemId = this.getFirstNDXProdIdentBlock2ItemId(this.NDXProdIdentBlockTable);
            this.SubId = nDXProdIdentBlock2ItemId.SubId;
            break;
    }
}

/// <summary>
/// PaffH 07.01.25
/// AX2009: tables.NDX_ProdIdent_Block2LabelArea.BlockName()
/// </summary>
/// <returns>NDXProdIdentBlockName</returns>
[SysClientCacheDataMethod(true)]
display NDXProdIdentBlockName blockName()
{
    if (this.NDXProdIdentBlockTable)
    {
        return NDXProdIdentBlockTable::findRecId(this.NDXProdIdentBlockTable).Name;
    }
    else if (this.AllRest == NoYes::Yes)
    {
        return "@NDX:NDXAllRestOnArea";
    }
    return '';
}
